export const EXPEDITION_TITLE='The Eastern Star';
export function freshExpedition(){return{phase:'locked'};}
export function restoreExpedition(v){return{phase:['locked','alexandria','courtyard','recorded','complete'].includes(v?.phase)?v.phase:'locked'};}
export function expeditionObjective(s){switch(s.expedition.phase){case'locked':return s.story.phase==='complete'?'Visit the cartographer’s archive in Lisbon to discover a new expedition.':'A new expedition awaits after the missing captain returns.';case'alexandria':return'Sail to Alexandria and visit the cartographer’s archive.';case'courtyard':return'Leave Alexandria by the caravan gate. Explore the Pilgrim’s Courtyard in the Holy Land.';case'recorded':return'Bring your copied star chart back to the archive in Alexandria.';default:return'The Eastern Star chart is preserved in Alexandria. Expedition complete.';}}
export function advanceExpedition(s,action,place){const q=s.expedition;let message;if(action==='accept'&&q.phase==='locked'&&s.story.phase==='complete'&&place==='lisbon-archive'){q.phase='alexandria';message='An old letter points to a star chart in the Holy Land. Visit Alexandria’s archive.';}else if(action==='read'&&q.phase==='alexandria'&&place==='alexandria-archive'){q.phase='courtyard';message='The archivist marked a caravan route to a quiet courtyard near Jerusalem. Leave Alexandria through the caravan gate.';}else if(action==='record'&&q.phase==='courtyard'&&place==='holyland'){q.phase='recorded';message='Copied the weathered star chart, leaving the original in its courtyard. Return to Alexandria’s archive.';}else if(action==='finish'&&q.phase==='recorded'&&place==='alexandria-archive'){q.phase='complete';s.gold+=450;message='The Eastern Star: your chart is preserved in Alexandria. Received 450 gold.';}else return{ok:false,message:'This part of the expedition is not ready yet.'};s.log.push(message);return{ok:true,message};}
